  string packed=Path.Combine(root,"tamper-fixture");Call(engine,"Extract",outer,packed);string support=Path.Combine(packed,"webvideo-plus/installer-support"),dll=Path.Combine(support,"7z.dll");byte[] original=File.ReadAllBytes(dll);original[0]^=1;File.WriteAllBytes(dll,original);Fails(()=>Call(engine,"RunDecoder",support,new[]{"i"}),"tampered decoder DLL rejected before execution");
  string corrupt=Path.Combine(payload,"component.json");File.AppendAllText(corrupt," ");Fails(()=>Call(engine,"ExtractPayload"),"changed cached payload rejected before use");Call(engine,"CleanupPayloadArtifacts");
  var canceled=New(Path.Combine(root,"pre-cancel"));engineType.GetField("Canceled").SetValue(canceled,true);Fails(()=>Call(canceled,"ExtractPayload"),"pre-cancel creates no ready cache");
