  using(var watcher=new FileSystemWatcher(cancelRoot,"*.js")){watcher.IncludeSubdirectories=true;watcher.Created+=(s,e)=>{observed=true;engineType.GetField("Canceled").SetValue(mid,true);};watcher.EnableRaisingEvents=true;
