  engineType.GetField("Canceled").SetValue(mid,false);string recovered=(string)Call(mid,"ExtractPayload");Check(File.Exists(Path.Combine(recovered,"WebGAL.Video.exe")),"retry after cancellation reuses archive and publishes verified payload");Call(mid,"CleanupPayloadArtifacts");
  string orphanRoot=Path.Combine(root,"orphan-cache"),orphanHash=new string('a',64),orphanPackages=Path.Combine(orphanRoot,"packages");var orphan=New(orphanRoot);File.WriteAllText(Path.Combine(orphanRoot,".webvideo-install-cache"),"owned");string owned=Path.Combine(orphanPackages,orphanHash.Substring(0,16)+".stage-"+Guid.NewGuid().ToString("N")),foreign=Path.Combine(orphanPackages,orphanHash.Substring(0,16)+".stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(owned);Directory.CreateDirectory(foreign);File.WriteAllText(Path.Combine(owned,"stage-owner"),orphanHash);File.WriteAllText(Path.Combine(foreign,"sentinel"),"keep");string partial=Path.Combine(orphanRoot,"payload-"+orphanHash+".zip.part-"+Guid.NewGuid().ToString("N"));File.WriteAllText(partial,"partial");Call(orphan,"CleanupStalePayloadArtifacts");Check(!Directory.Exists(owned)&&!File.Exists(partial)&&File.Exists(Path.Combine(foreign,"sentinel")),"owned crash staging reclaimed while unmarked directory preserved");
  Console.WriteLine(new JavaScriptSerializer().Serialize(new{passed=passed,freshExtractionSeconds=freshSeconds,verifiedCacheSeconds=cacheSeconds,results=results}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
